    int findMinStep(string board, string hand) {
        sort(hand.begin(), hand.end());
        queue<tuple<string, string, int>> q;
        unordered_set<string> visited;

        q.push({board, hand, 0});
        visited.insert(board + "#" + hand);

        while (!q.empty()) {
            auto [currB, currH, step] = q.front();
            q.pop();
            if (currB.empty()) return step;

            for (int i = 0; i < (int)currH.size(); i++) {
                if (i > 0 && currH[i] == currH[i - 1]) continue;
                char c = currH[i];
