class Solution {
    private String clean(String s) {
        boolean collapsed = true;
        while (collapsed) {
            collapsed = false;
            for (int i = 0; i < s.length();) {
                int j = i;
                while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
                if (j - i >= 3) {
                    s = s.substring(0, i) + s.substring(j);
                    collapsed = true;
                    break;
                } else {
                    i = j;
                }
            }
        }
        return s;
    }

    public int findMinStep(String board, String hand) {
        char[] hArr = hand.toCharArray();
        Arrays.sort(hArr);
        hand = new String(hArr);

        Queue<String[]> q = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        q.offer(new String[]{board, hand, "0"});
        visited.add(board + "#" + hand);

        while (!q.isEmpty()) {
            String[] cur = q.poll();
            String currB = cur[0], currH = cur[1];
            int step = Integer.parseInt(cur[2]);
            if (currB.isEmpty()) return step;

            for (int i = 0; i < currH.length(); i++) {
                if (i > 0 && currH.charAt(i) == currH.charAt(i - 1)) continue;
                char c = currH.charAt(i);
                String nextH = currH.substring(0, i) + currH.substring(i + 1);

                for (int j = 0; j <= currB.length(); j++) {
                    if (j > 0 && currB.charAt(j - 1) == c) continue;
                    boolean pick = false;
                    if (j < currB.length() && currB.charAt(j) == c) pick = true;
                    else if (j > 0 && j < currB.length() && currB.charAt(j - 1) == currB.charAt(j) && currB.charAt(j) != c) pick = true;
                    if (pick) {
                        String nb = clean(currB.substring(0, j) + c + currB.substring(j));
                        String state = nb + "#" + nextH;
                        if (!visited.contains(state)) {
                            visited.add(state);
                            q.offer(new String[]{nb, nextH, String.valueOf(step + 1)});
                        }
                    }
                }
            }
        }
        return -1;
    }
}

var findMinStep = function(board, hand) {
    function clean(s) {
        let collapsed = true;
        while (collapsed) {
            collapsed = false;
            for (let i = 0; i < s.length;) {
                let j = i;
                while (j < s.length && s[j] === s[i]) j++;
                if (j - i >= 3) {
                    s = s.slice(0, i) + s.slice(j);
                    collapsed = true;
                    break;
                } else {
                    i = j;
                }
            }
        }
        return s;
    }

    const sortedHand = hand.split("").sort().join("");
    const queue = [[board, sortedHand, 0]];
    const visited = new Set();
    visited.add(board + "#" + sortedHand);

    while (queue.length > 0) {
        const [currB, currH, step] = queue.shift();
        if (currB.length === 0) return step;

        for (let i = 0; i < currH.length; i++) {
            if (i > 0 && currH[i] === currH[i - 1]) continue;
            const c = currH[i];
            const nextH = currH.slice(0, i) + currH.slice(i + 1);

            for (let j = 0; j <= currB.length; j++) {
                if (j > 0 && currB[j - 1] === c) continue;
                let pick = false;
                if (j < currB.length && currB[j] === c) pick = true;
                else if (j > 0 && j < currB.length && currB[j - 1] === currB[j] && currB[j] !== c) pick = true;
                if (pick) {
                    const nb = clean(currB.slice(0, j) + c + currB.slice(j));
                    const state = nb + "#" + nextH;
